class Solution {
  public long countGoodSubarrays(int[] nums) {
    int n = nums.length;
    int[] prevGE = new int[n],
        nextG = new int[n],
        badLeft = new int[n],
        badRight = new int[n],
        stack = new int[n];
    int sp = 0;
    for (int i = 0; i < n; i++) {
      while (sp > 0 && nums[stack[sp - 1]] < nums[i]) sp--;
      prevGE[i] = sp == 0 ? -1 : stack[sp - 1];
      stack[sp++] = i;
    }
    sp = 0;
    for (int i = n - 1; i >= 0; i--) {
      while (sp > 0 && nums[stack[sp - 1]] <= nums[i]) sp--;
      nextG[i] = sp == 0 ? n : stack[sp - 1];
      stack[sp++] = i;
    }
    int[] last = new int[31];
    java.util.Arrays.fill(last, -1);
    for (int i = 0; i < n; i++) {
      int bad = -1;
      for (int b = 0; b < 31; b++) if ((nums[i] >> b & 1) == 0) bad = Math.max(bad, last[b]);
      badLeft[i] = bad;
      for (int b = 0; b < 31; b++) if ((nums[i] >> b & 1) != 0) last[b] = i;
    }
    int[] first = new int[31];
    java.util.Arrays.fill(first, n);
    for (int i = n - 1; i >= 0; i--) {
      int bad = n;
      for (int b = 0; b < 31; b++) if ((nums[i] >> b & 1) == 0) bad = Math.min(bad, first[b]);
      badRight[i] = bad;
      for (int b = 0; b < 31; b++) if ((nums[i] >> b & 1) != 0) first[b] = i;
    }
    long total = 0;
    for (int i = 0; i < n; i++) {
      int lo = Math.max(prevGE[i], badLeft[i]), hi = Math.min(nextG[i], badRight[i]);
      total += (long) (i - lo) * (hi - i);
    }
    return total;
  }
}
